/** Run desugaring phases that must occur before disambiguation.
 *  1) Rewrite trait, object, and object expressions to explicitly extend Object
 *     if no explicit bounds, or only Any, were given, and to extend Object beside
 *     Index if only Index and Any were given; the traits Any and Object, and the
 *     library's trait Index, are left as written.  Also rewrite static parameter bindings
 *     to explicitly extend Object if no explicit bounds were given.
 *  2) Remove conditional operators, replacing their operands with thunks.
 *  Desugar conditional operators into operators that take thunks.
 *  This desugaring is described in section 22.8 of the specification.
 *  We find {@code e_1 AND: e_2}, for example, and change it into
 *  {@code e_1 AND (fn () => e_2)}, for which an overloading must exist.
 *  This desugaring must go before disambiguation, and is therefore called
 *  by {@code PreDisambiguationDesugarer}.
 *  3) Rewrite reductions to explicit invocations of big operators.
 *  4) Desugar compound assignments (this requires identifying subexpressions of LHS)
 *  5) Desugar subscripting expressions to method calls.
 *  6) Desugar subscripting assignments
 */
public class PreDisambiguationDesugaringVisitor extends NodeUpdateVisitor {

    private final Id anyTypeId = NodeFactory.makeId(NodeFactory.makeSpan("singleton"), WellKnownNames.anyTypeName);
    private final Id objectTypeId = NodeFactory.makeId(NodeFactory.makeSpan("singleton"), WellKnownNames.objectTypeName);

    /** The name of the api or component visited. */
    private String unitName = "";

    @Override
    public Node forComponent(Component that) {
        unitName = that.getName().getText();
        return super.forComponent(that);
    }

    @Override
    public Node forApi(Api that) {
        unitName = that.getName().getText();
        return super.forApi(that);
    }

    /** True if the type is named name. */
    private static boolean isNamed(BaseType type, String name) {
        return type instanceof NamedType && ((NamedType)type).getName().getText().equals(name);
    }

    /** True if each type of the extends clause is Any, as in an empty clause. */
    private static boolean namesOnlyAny(List<TraitTypeWhere> extendsClause) {
        for (TraitTypeWhere entry : extendsClause) {
            if ( ! isNamed(entry.getBaseType(), WellKnownNames.anyTypeName) )
                return false;
        }
        return true;
    }

    /** True if each type of the extends clause is Any or Index. */
    private static boolean namesOnlyAnyOrIndex(List<TraitTypeWhere> extendsClause) {
        for (TraitTypeWhere entry : extendsClause) {
            BaseType type = entry.getBaseType();
            if ( ! isNamed(type, WellKnownNames.anyTypeName) &&
                 ! isNamed(type, WellKnownNames.indexTypeName) )
                return false;
        }
        return true;
    }

    /** If the extends clause of a trait declaration, an object declaration, or
     *  an object expression is empty or names only Any, then replace it
     *  with {Object}.  If it names only Index and Any, then replace it with
     *  its Index entries and Object: the library's Index extends Any and not
     *  Object, so a type that extends only Index extends Object too.
     */
    private List<TraitTypeWhere> rewriteExtendsClause(Node whence,
                                                      List<TraitTypeWhere> extendsClause) {
        if ( ! namesOnlyAnyOrIndex(extendsClause) ) return extendsClause;
        if ( ! ( whence instanceof ASTNode ) )
            bug(whence, "Only ASTNodes are supported.");
        Id objectId = NodeFactory.makeId(NodeUtil.getSpan((ASTNode)whence),
                                         WellKnownNames.objectTypeName);
        TraitType typeObject = NodeFactory.makeTraitType(objectId);
        TraitTypeWhere extendsObject = NodeFactory.makeTraitTypeWhere(typeObject);
        if ( namesOnlyAny(extendsClause) ) return Collections.singletonList(extendsObject);
        List<TraitTypeWhere> result = new ArrayList<TraitTypeWhere>();
        for (TraitTypeWhere entry : extendsClause) {
            if ( isNamed(entry.getBaseType(), WellKnownNames.indexTypeName) ) result.add(entry);
        }
        result.add(extendsObject);
        return result;
    }

    /** True if the trait declaration is the library's trait Index, which
     *  extends Any as Object does, and not Object. */
    private boolean isLibraryIndex(TraitDecl that) {
        return unitName.equals(WellKnownNames.fortressLibrary()) &&
               NodeUtil.getName(that).getText().equals(WellKnownNames.indexTypeName);
    }

    /** If the extends clause of a static parameter is empty,
     *  then replace the empty extends clause with {Object}.
     */
    private List<BaseType> rewriteStaticParamExtendsClause(Node whence,
                                                           List<BaseType> extendsClause) {
        if (extendsClause.size() > 0) return extendsClause;
        if ( ! ( whence instanceof ASTNode ) )
            bug(whence, "Only ASTNodes are supported.");
        Id objectId = NodeFactory.makeId(NodeUtil.getSpan((ASTNode)whence),
                                         WellKnownNames.objectTypeName);
        TraitType typeObject = NodeFactory.makeTraitType(objectId);
        return Collections.singletonList((BaseType)typeObject);
    }

    @Override
        public Node forObjectExprOnly(ObjectExpr that,
                                      ExprInfo info,
                                      TraitTypeHeader header,
                                      Option<SelfType> selfType) {
    	SelfTypeBoundsInserter bi = new SelfTypeBoundsInserter();
    	that = (ObjectExpr)that.accept(bi);
    	header = (TraitTypeHeader)header.accept(bi);
        Span span = NodeUtil.getSpan(that);
        List<TraitTypeWhere> extendsClause = rewriteExtendsClause(that, header.getExtendsClause());
        header = NodeFactory.makeTraitTypeHeader(NodeFactory.makeId(span,"_"),
                                                 extendsClause,
                                                 header.getDecls());
        return super.forObjectExprOnly(that, info, header, selfType);
    }

    @Override
        public Node forTraitDecl(TraitDecl that) {
    	that = (TraitDecl)that.accept(new SelfTypeBoundsInserter());
        TraitTypeHeader header_result = (TraitTypeHeader) recur(that.getHeader());
        List<BaseType> excludesClause_result = recurOnListOfBaseType(that.getExcludesClause());
        Option<List<NamedType>> comprisesClause_result = recurOnOptionOfListOfNamedType(that.getComprisesClause());

        if (!NodeUtil.getName(that).equals(anyTypeId) &&
            !NodeUtil.getName(that).equals(objectTypeId) &&
            !isLibraryIndex(that)) {
            header_result = NodeFactory.makeTraitTypeHeader(header_result,
                                                            rewriteExtendsClause(that, header_result.getExtendsClause()));
        }

        return super.forTraitDeclOnly(that, that.getInfo(), header_result,
                                      that.getSelfType(),
                                      excludesClause_result,
                                      comprisesClause_result);
    }

    @Override
        public Node forObjectDecl(ObjectDecl that) {
    	that = (ObjectDecl)that.accept(new SelfTypeBoundsInserter());
        TraitTypeHeader header_result = (TraitTypeHeader) recur(that.getHeader());
        Option<List<Param>> params_result = recurOnOptionOfListOfParam(NodeUtil.getParams(that));
        header_result = NodeFactory.makeTraitTypeHeader(header_result,
                                                        rewriteExtendsClause(that, header_result.getExtendsClause()),
                                                        params_result);
        return super.forObjectDeclOnly(that, that.getInfo(),
                                       header_result, that.getSelfType());
    }

    @Override
    public Node forStaticParam(StaticParam that) {
	if (!Shell.getExtendsObjectPreDesugaring()) {
	    return super.forStaticParam(that);
	} else {
	    ASTNodeInfo info_result = (ASTNodeInfo) recur(that.getInfo());
	    IdOrOp name_result = (IdOrOp) recur(that.getName());
	    List<BaseType> extendsClause_result = recurOnListOfBaseType(that.getExtendsClause());
	    List<BaseType> dominatesClause_result = recurOnListOfBaseType(that.getDominatesClause());
	    Option<Type> dimParam_result = recurOnOptionOfType(that.getDimParam());
	    StaticParamKind kind_result = (StaticParamKind) recur(that.getKind());
		extendsClause_result = rewriteStaticParamExtendsClause(that, extendsClause_result);
	    return forStaticParamOnly(that, info_result, name_result, extendsClause_result, dominatesClause_result, dimParam_result, kind_result);
	}
    }

    @Override
    public Node forAmbiguousMultifixOpExpr(AmbiguousMultifixOpExpr that) {
        // If there is a colon at all, the operator is no longer ambiguous:
        // It must be infix.
        IdOrOp name = that.getInfix_op().getNames().get(0);
        if ( ! (name instanceof Op) )
            return bug(name, "The name field of OpRef should be Op.");
        Op op_name = (Op)name;
        boolean prefix = OprUtil.hasPrefixColon(op_name);
        boolean suffix = OprUtil.hasSuffixColon(op_name);

        if( prefix || suffix ) {
            OpExpr new_op = ExprFactory.makeOpExpr(NodeUtil.getSpan(that),
                                                   NodeUtil.isParenthesized(that),
                                                   NodeUtil.getExprType(that),
                                                   that.getInfix_op(),
                                                   that.getArgs());
            return recur(new_op);
        }
        else {
            return super.forAmbiguousMultifixOpExpr(that);
        }
    }

