package com.sun.fortress.compiler.runtimeValues;
import java.util.concurrent.atomic.AtomicLong;
import com.sun.fortress.runtimeSystem.Naming;
public abstract class RTTI {
    private static final AtomicLong snCount = new AtomicLong(0);
    final Class javaRep;
    private final long serialNumber;
    public boolean runtimeSupertypeOf(RTTI other) {
        boolean result =  this.javaRep.isAssignableFrom( other.javaRep );
        // System.err.println(other.toString() + (result ? " <: " : " not<: ")+ this.toString());
        return result;
    }
    public RTTI(Class javaRep) {
        this.javaRep = javaRep;
        this.serialNumber = snCount.getAndIncrement();
    }
    /*
     * Long term, this will need to be done lazily because
     * of issues generating appropriate bytecodes for methods
     * appearing in some generics -- nominal union types will
     * need to be canonicalized to a form that might not be a
     * union, depending upon subtype relations that might depend
     * on this class itself.
     */
    public RTTI(String javaRep) {
        try {
            this.javaRep = Class.forName(javaRep);
        } catch (ClassNotFoundException ex) {
            throw new Error(ex);
        }
        this.serialNumber = snCount.getAndIncrement();
    }
    public int hashCode() { return javaRep.hashCode(); }
    public String className() {
        String className = javaRep.getCanonicalName();
        String deMangle = Naming.demangleFortressIdentifier(className);
        String noDots = Naming.dotToSep(deMangle);
        return noDots;
    }
    public long getSN() {
        return this.serialNumber;
    }
    public String toString() {
        return serialNumber + ":" + javaRep.getSimpleName();
    }
}

package com.sun.fortress.compiler.runtimeValues;

import com.sun.fortress.runtimeSystem.Naming;

public abstract class TupleRTTI extends RTTI {

    final RTTI[] elementRTTI;

    public TupleRTTI(Class javaRep, RTTI[] elements) {
        super(javaRep);
        elementRTTI = elements;
    }

    /**
     * Tupled covariant extension-of test.
     */
    public boolean runtimeSupertypeOf(RTTI other) {
        if (super.runtimeSupertypeOf(other))
            return true;
        if (! (other instanceof TupleRTTI))
            return false;
        RTTI[] otherRTTI = ((TupleRTTI) other).elementRTTI;
        if (otherRTTI.length != elementRTTI.length)
            return false;
        for (int i = 0; i < elementRTTI.length; i++) {
            if (! elementRTTI[i].runtimeSupertypeOf(otherRTTI[i]))
                return false;
        }
        return true;
    }

    public String className() {
        StringBuilder ret = new StringBuilder(Naming.CONCRETE_TUPLE + Naming.LEFT_OXFORD);
        for (int i = 0; i < this.elementRTTI.length -1; i++)
            ret.append(this.elementRTTI[i].className() + Naming.GENERIC_SEPARATOR);
        ret.append(this.elementRTTI[this.elementRTTI.length-1].className() + Naming.RIGHT_OXFORD);
        return ret.toString();
    }
}

